const body = $input.first().json.body || {};

const image_url = body.image_url || null;
const site_id = body.site_id || 'unknown';

if (!image_url || image_url.trim().length === 0) {
  throw new Error('Missing required field: image_url not found in request body.');
}

return [{
  json: {
    image_url: image_url.trim(),
    site_id: site_id
  }
}];

// Get the binary data object
const binaryData = $input.first().binary;

// Use the internal n8n helper to force-read the file from disk into memory
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buffer) {
  throw new Error('Failed to extract image data from disk.');
}

// Convert the buffer to a base64 string
const base64String = buffer.toString('base64');
const mediaType = binaryData.mimeType || 'image/jpeg';

return [{
  json: {
    image_base64: base64String,
    media_type: mediaType,
    site_id: $input.first().json.site_id
  }
}];

const image_base64 = $input.item.json.image_base64;
const media_type = $input.item.json.media_type;
const site_id = $input.item.json.site_id;

const auditPrompt = "You are a strict Fire Safety Compliance Auditor operating under NBC 2016 and CFO Mumbai norms. Inspect this image of fire safety equipment and evaluate compliance. Check for: 1) Pressure gauges — needle must be in green zone; 2) Safety pin — must be intact and sealed with tamper tag; 3) ISI mark — must be visible on cylinder body; 4) Hose reel glass — must be unbroken; 5) Expiry date — must not be expired; 6) Physical damage — no dents, rust, or corrosion; 7) Mounting — must be properly mounted at correct height; 8) Signage — inspection tag must be present and current. Return ONLY valid JSON with no markdown, no explanation, no code blocks. Exact schema: {\"equipment_type\": \"string\", \"status\": \"COMPLIANT or NON-COMPLIANT\", \"confidence\": \"HIGH or MEDIUM or LOW\", \"observations\": \"string describing what you see\", \"violations\": [\"list of violation strings, empty array if compliant\"]}";

const payload = {
  model: 'anthropic/claude-3-7-sonnet',
  max_tokens: 1024,
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'image_url',
          image_url: {
            url: `data:${media_type};base64,${image_base64}`
          }
        },
        {
          type: 'text',
          text: auditPrompt
        }
      ]
    }
  ]
};

return [{
  json: {
    payload: payload,
    site_id: site_id
  }
}];

const raw = $input.first().json.choices?.[0]?.message?.content || '';

let cleaned = raw
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    equipment_type: 'Unknown',
    status: 'ERROR',
    confidence: 'LOW',
    observations: 'Failed to parse AI response: ' + e.message,
    violations: ['AI_PARSE_ERROR']
  };
}

const site_id = $('BUILD_Vision_Payload').first().json.site_id || 'unknown';

return [{
  json: {
    ...parsed,
    site_id: site_id,
    audit_timestamp: new Date().toISOString()
  }
}];

const status = $input.item.json.status;
const site_id = $input.item.json.site_id;

let violations = $input.item.json.violations || [];
if (typeof violations === 'string') {
  try { violations = JSON.parse(violations); } 
  catch (e) { violations = [violations]; }
}
if (!Array.isArray(violations)) violations = [String(violations)];

let reinspect_reasons = $input.item.json.reinspect_reasons || [];
if (typeof reinspect_reasons === 'string') {
  try { reinspect_reasons = JSON.parse(reinspect_reasons); } 
  catch (e) { reinspect_reasons = [reinspect_reasons]; }
}
if (!Array.isArray(reinspect_reasons)) reinspect_reasons = [String(reinspect_reasons)];

const equipment = $input.item.json.equipment_type || 'Unknown Equipment';
const confidence = $input.item.json.confidence || 'N/A';
const timestamp = $input.item.json.audit_timestamp || new Date().toISOString();

// Format timestamp for India
const indiaTime = new Date(timestamp).toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata',
  dateStyle: 'medium',
  timeStyle: 'short'
});

let title, emoji, items, actionText;

if (status === 'NON-COMPLIANT') {
  title = 'AUDIT FAILED — IMMEDIATE ACTION REQUIRED';
  emoji = '🔴';
  items = violations;
  actionText = 'Notify site supervisor and schedule immediate maintenance.';
} else if (status === 'REINSPECT') {
  title = 'REINSPECT REQUIRED — PHOTO QUALITY ISSUE';
  emoji = '📸';
  items = reinspect_reasons;
  actionText = 'Request field technician to retake photos with better clarity.';
} else {
  title = 'AUDIT STATUS: ' + status;
  emoji = '⚪';
  items = violations;
  actionText = 'Review required.';
}

const itemList = items.length > 0
  ? items.map((v, i) => `${i + 1}. ${v}`).join('\n')
  : 'None recorded';

// PLAIN TEXT VERSION (Telegram + Email)
const plainAlert = `${emoji} ${title}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Site ID     : ${site_id}
Equipment   : ${equipment}
Status      : ${status}
Confidence  : ${confidence}
Timestamp   : ${indiaTime}

 ${status === 'NON-COMPLIANT' ? 'VIOLATIONS DETECTED:' : 'ITEMS THAT COULD NOT BE VERIFIED:'}
 ${itemList}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Action: ${actionText}`;

// SLACK MARKDOWN VERSION
const slackAlert = `:fire: *${title}*
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
*Site ID:* \`${site_id}\`
*Equipment:* ${equipment}
*Status:* \`${status}\`
*Confidence:* ${confidence}
*Timestamp:* ${indiaTime}

*${status === 'NON-COMPLIANT' ? 'VIOLATIONS DETECTED:' : 'ITEMS THAT COULD NOT BE VERIFIED:'}*
 ${items.map(v => `• ${v}`).join('\n')}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
*Action:* ${actionText}`;

// EMAIL HTML VERSION
const htmlAlert = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #ddd; border-radius: 8px; overflow: hidden;">
  <div style="background: ${status === 'NON-COMPLIANT' ? '#dc2626' : '#f59e0b'}; color: white; padding: 20px; text-align: center;">
    <h2 style="margin: 0;">${emoji} ${title}</h2>
  </div>
  <div style="padding: 20px; background: #f9fafb;">
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px; border-bottom: 1px solid #e5e7eb; font-weight: bold;">Site ID</td><td style="padding: 8px; border-bottom: 1px solid #e5e7eb;">${site_id}</td></tr>
      <tr><td style="padding: 8px; border-bottom: 1px solid #e5e7eb; font-weight: bold;">Equipment</td><td style="padding: 8px; border-bottom: 1px solid #e5e7eb;">${equipment}</td></tr>
      <tr><td style="padding: 8px; border-bottom: 1px solid #e5e7eb; font-weight: bold;">Status</td><td style="padding: 8px; border-bottom: 1px solid #e5e7eb;"><strong style="color: ${status === 'NON-COMPLIANT' ? '#dc2626' : '#f59e0b'};">${status}</strong></td></tr>
      <tr><td style="padding: 8px; border-bottom: 1px solid #e5e7eb; font-weight: bold;">Confidence</td><td style="padding: 8px; border-bottom: 1px solid #e5e7eb;">${confidence}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Timestamp</td><td style="padding: 8px;">${indiaTime}</td></tr>
    </table>
  </div>
  <div style="padding: 20px;">
    <h3 style="color: #374151; margin-top: 0;">${status === 'NON-COMPLIANT' ? '🚨 Violations Detected:' : '📸 Items That Could Not Be Verified:'}</h3>
    <ul style="color: #4b5563;">
      ${items.map(v => `<li style="padding: 4px 0;">${v}</li>`).join('')}
    </ul>
  </div>
  <div style="background: #eff6ff; padding: 15px 20px; border-top: 1px solid #ddd;">
    <strong>⚠️ Required Action:</strong> ${actionText}
  </div>
  <div style="background: #f3f4f6; padding: 10px 20px; font-size: 12px; color: #6b7280; text-align: center;">
    FireScan Mumbai | Powered by Arvami Solutionz | ${indiaTime}
  </div>
</div>`;

return [{
  json: {
    // Plain text for Telegram
    telegram_message: plainAlert,
    // Slack markdown
    slack_message: slackAlert,
    // HTML for email
    email_html: htmlAlert,
    email_subject: `${emoji} Fire Audit ${status}: ${site_id}`,
    // Keep original fields
    alert: plainAlert,
    site_id: site_id,
    status: status,
    equipment_type: equipment,
    violations: violations,
    reinspect_reasons: reinspect_reasons,
    audit_timestamp: timestamp
  }
}];
